import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
const PIECES=new Set(['cover','obstacle','wheel','fuse','newFuse','newWheel','plug']);
const DESTINATIONS={cover:['tray','coverSeat'],obstacle:['tray'],wheel:['tray'],fuse:['tray'],newFuse:['fuseSocket'],newWheel:['wheelHub'],plug:['port']};
export function makeRepairRig(id){
 const group=new THREE.Group(),parts={};group.name='Banco_'+id;const add=(key,geo,color,x,y,z=.2)=>{const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color,metalness:.35,roughness:.5}));mesh.position.set(x,y,z);mesh.userData.handTarget=key;group.add(mesh);if(key)parts[key]=mesh;return mesh;},box=(key,color,x,y,w,h,d=.1,z=.2)=>add(key,new THREE.BoxGeometry(w,h,d),color,x,y,z),round=(key,color,x,y,r=.1,z=.4)=>add(key,new THREE.SphereGeometry(r,20,12),color,x,y,z);
 box('',0x263d50,0,0,3.5,2.75,.12,0);box('power',0x9cbfa3,-1.45,1.06,.38,.26,.18,.26);box('tray',0x5b7587,2.4,-.88,1.15,.18,.8,.2);
 if(id==='doors'){box('',0x9eabb3,0,.0,2.45,2.35,.14,.10);box('',0x172d3c,0,.0,2.20,2.12,.15,.20);box('doorSlideLeft',0x6892a4,-.51,0,1,2.06,.09,.32);box('doorSlideRight',0x6892a4,.51,0,1,2.06,.09,.32);box('obstacle',0xe3aa4c,0,-.9,.34,.35,.2,.53);}
 else if(id==='running'){const wheel=(key,color,x,y)=>{const o=add(key,new THREE.CylinderGeometry(.82,.82,.20,40),color,x,y,.35);o.rotation.order='ZXY';o.rotation.x=Math.PI/2;const stripe=new THREE.Mesh(new THREE.BoxGeometry(.07,.22,1.15),new THREE.MeshStandardMaterial({color:0xe5bd73}));stripe.position.y=-.13;o.add(stripe);return o;};round('wheelHub',0x9cb7ca,0,0,.32,.2);wheel('wheel',0x344753,0,0);wheel('newWheel',0x659885,2.4,.1);box('stand',0xd2a74f,0,-1.12,1.6,.24,.4,.2);round('bolt1',0xc2cfd8,.30,.10,.09,.65);round('bolt2',0xc2cfd8,-.30,-.10,.09,.65);box('',0x7d9fb5,0,0,.07,1.25,.06,.49);}
 else {box('coverSeat',0x3b6477,0,.15,2.05,1.65,.035,.1);box('cover',0x93aab5,0,.15,2.05,1.65,.09,.62);box('coverTray',0x93aab5,2.4,.86,1.1,.85,.09,.5).userData.handTarget='cover';round('screw1',0xd1e0e5,-1.15,.90,.11,.70);round('screw2',0xd1e0e5,1.15,.90,.11,.70);
 if(id==='ventilation'){const rotor=new THREE.Group();group.add(rotor);parts.rotor=rotor;rotor.position.set(0,.27,.3);for(let i=0;i<4;i++){const blade=box('',0xabc3cb,0,0,.20,.62,.06,.3);group.remove(blade);rotor.add(blade);blade.position.set(Math.sin(i*Math.PI/2)*.30,Math.cos(i*Math.PI/2)*.30,0);blade.rotation.z=-i*Math.PI/2;}box('port',0x96c2c5,.7,-.54,.45,.24,.14,.32);box('plug',0xe1b45c,-.75,-.50,.45,.24,.14,.34);box('testFan',0x90b5a0,0,-1.10,1.35,.25,.15,.25);}
 else{box('fuseSocket',0x303f4d,0,.2,1.08,.29,.12,.22);box('fuse',0xe4ad66,0,.2,.75,.17,.12,.34);box('newFuse',0x7fb09a,2.4,.25,.75,.17,.12,.34);for(const [key,x,y,c]of [['sourcePlus',-1.3,-.82,0xe06c64],['return',-.88,-.82,0x555d66],['fuseA',-.55,.20,0xd76360],['fuseB',.55,.20,0x697f90],['lampPlus',.90,-.82,0xd76360],['lampMinus',1.32,-.82,0x697f90]])round(key,c,x,y,.11,.45);round('lamp',0x7e8076,1.35,.86,.17,.3);parts.lamp.userData.handTarget='';}}
 for(const [key,part]of Object.entries(parts)){if(key.startsWith('screw')||key.startsWith('bolt')){const slot=new THREE.Mesh(new THREE.BoxGeometry(.15,.026,.015),new THREE.MeshStandardMaterial({color:0x455d71}));slot.position.z=.105;part.add(slot);}if(key.startsWith('doorSlide')){const glass=new THREE.Mesh(new THREE.BoxGeometry(.63,.65,.026),new THREE.MeshStandardMaterial({color:0xb2d5e0,metalness:.1,roughness:.25}));glass.position.set(0,.45,.064);part.add(glass);}}

 // Industrial fixtures and labels belong to the same rig; they do not intercept picking.
 const steel=new THREE.MeshStandardMaterial({color:0x748b98,metalness:.78,roughness:.3}),rubber=new THREE.MeshStandardMaterial({color:0x15252f,roughness:.85});
 for(const x of [-1.70,1.70]){const rail=new THREE.Mesh(new THREE.BoxGeometry(.05,2.65,.10),steel);rail.position.set(x,0,.08);group.add(rail);}
 const shelf=new THREE.Mesh(new THREE.BoxGeometry(5.8,.09,.9),steel);shelf.position.set(.65,-1.48,.12);group.add(shelf);
 for(const x of [-1.61,1.61])for(const y of [-1.23,1.23]){const screw=new THREE.Mesh(new THREE.CylinderGeometry(.027,.027,.025,16),steel);screw.rotation.x=Math.PI/2;screw.position.set(x,y,.09);group.add(screw);}
 if(id==='electrical')for(const coords of [[[-1.3,-.82],[-1.3,.2],[-.55,.2]],[[.55,.2],[.9,.2],[.9,.86],[1.35,.86]],[[-.88,-.82],[-.88,-1.15],[1.32,-1.15],[1.32,-.82]]]){const curve=new THREE.CatmullRomCurve3(coords.map(([x,y])=>new THREE.Vector3(x,y,.16)));const wire=new THREE.Mesh(new THREE.TubeGeometry(curve,24,.018,6,false),rubber);group.add(wire);}
 if(id==='running')for(const key of ['wheel','newWheel']){const tire=parts[key],ring=new THREE.Mesh(new THREE.TorusGeometry(.68,.15,12,40),rubber);ring.rotation.x=Math.PI/2;tire.add(ring);const rim=new THREE.Mesh(new THREE.CylinderGeometry(.47,.47,.225,36),steel);tire.add(rim);for(let i=0;i<6;i++){const stud=new THREE.Mesh(new THREE.CylinderGeometry(.026,.026,.045,12),steel);stud.position.set(Math.cos(i*Math.PI/3)*.28,.14,Math.sin(i*Math.PI/3)*.28);tire.add(stud);}}
 if(id==='doors')for(const key of ['doorSlideLeft','doorSlideRight']){const leaf=parts[key];for(const x of [-.47,.47]){const edge=new THREE.Mesh(new THREE.BoxGeometry(.025,2,.035),steel);edge.position.set(x,0,.065);leaf.add(edge);}}
 for(const [key,label]of Object.entries({power:'S1 · ALIMENTACIÓN',tray:'BANDEJA',stand:'APOYO',sourcePlus:'TP+',return:'TP−',fuseA:'F1 A',fuseB:'F1 B',lampPlus:'H+',lampMinus:'H−',testFan:'ENSAYO',port:'PUERTO',plug:'CONECTOR',newFuse:'REPUESTO F1'})){const part=parts[key];if(!part)continue;const canvas=globalThis.document?.createElement?.('canvas'),c=canvas?.getContext?.('2d');if(!c)continue;canvas.width=512;canvas.height=96;c.fillStyle='#172e3c';c.fillRect(0,0,512,96);c.fillStyle='#c4d9e3';c.textAlign='center';c.textBaseline='middle';c.font='bold 35px Arial';c.fillText(label,256,48);const map=new THREE.CanvasTexture(canvas);map.colorSpace=THREE.SRGBColorSpace;const tag=new THREE.Mesh(new THREE.PlaneGeometry(key==='power'?.65:.45,.095),new THREE.MeshBasicMaterial({map,side:THREE.DoubleSide}));const q=part.quaternion.clone().invert();tag.position.set(0,key==='tray'?-.19:.20,.16).applyQuaternion(q);tag.quaternion.copy(q);part.add(tag);}
 return {group,parts,id};
}
export function updateRepairRig(rig,state){const p=rig.parts;rig.group.visible=true;p.power.material.color.set(state.power?0x8ebe9b:0xce9250);if(state.id==='doors'){p.obstacle.visible=state.obstacle;p.doorSlideLeft.position.x=-.51-state.doorPosition/100;p.doorSlideRight.position.x=.51+state.doorPosition/100;}
 else if(state.id==='running'){p.wheel.visible=!state.wheelRemoved;p.newWheel.visible=!state.wheelReplaced;p.stand.material.color.set(state.standLocked?0x86bea0:0xd2a74f);if(state.wheelReplaced){p.newWheel.visible=true;if(state.selectedItem!=='newWheel')p.newWheel.position.set(0,0,.35);p.newWheel.userData.handTarget='wheelHub';p.newWheel.rotation.z=state.rotation*Math.PI/180;}for(let i=0;i<2;i++)p['bolt'+(i+1)].material.color.set(state.wheelBolts[i]?0x8fcca5:0xc2cfd8);}
 else {p.cover.visible=!state.coverOpen;p.coverTray.visible=state.coverOpen;p.coverSeat.visible=state.coverOpen;p.screw1.position.z=state.screws[0]?.70:.88;p.screw2.position.z=state.screws[1]?.70:.88;if(state.id==='ventilation'){p.rotor.visible=state.coverOpen;p.plug.visible=state.coverOpen&&!state.plugConnected;p.port.visible=state.coverOpen;}else{p.fuse.visible=state.coverOpen&&!state.fuseRemoved;p.fuseSocket.visible=state.coverOpen;p.fuseA.visible=p.fuseB.visible=state.coverOpen;p.fuse.material.color.set(state.fuseReplaced?0x85bc9c:0xe4ad66);const on=state.power&&state.fuseReplaced&&!state.fuseRemoved;p.lamp.material.emissive.set(on?0xffde86:0x000000);p.lamp.material.color.set(on?0xffe5a5:0x777b77);p.newFuse.visible=!state.fuseReplaced;}}
 if(state.toolMotion&&p[state.toolMotion.target])p[state.toolMotion.target].rotation.z=state.toolMotion.progress*2*Math.PI;
}
function disposeRig(rig){rig.group.traverse(o=>{o.geometry?.dispose();if(o.material){o.material.map?.dispose();o.material.dispose();}});}
export class RepairScene{
 constructor(canvas,handlers){this.canvas=canvas;this.handlers=handlers;this.scene=new THREE.Scene();this.scene.background=new THREE.Color('#122333');this.scene.add(new THREE.HemisphereLight(0xe5f4ff,0x314151,2.9));const light=new THREE.DirectionalLight(0xffeac7,3);light.position.set(-3,6,5);this.scene.add(light);this.camera=new THREE.PerspectiveCamera(39,1,.05,40);this.camera.position.set(.8,.8,7.7);this.controls=new OrbitControls(this.camera,canvas);this.controls.target.set(.65,0,0);this.controls.enableRotate=false;this.controls.mouseButtons.LEFT=null;this.controls.mouseButtons.RIGHT=THREE.MOUSE.PAN;this.controls.enableZoom=true;this.controls.minDistance=4;this.controls.maxDistance=12;this.controls.update();this.renderer=new THREE.WebGLRenderer({canvas,antialias:true});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.ray=new THREE.Raycaster();this.pointer=new THREE.Vector2();this.visible=true;this.clock=new THREE.Clock();this.bindInput();new ResizeObserver(()=>this.resize()).observe(canvas);this.resize();this.frame();}
 bindInput(){
 // Primary work gestures never reach OrbitControls (which owns pan/zoom only).
 const canvas=this.canvas;
 canvas.addEventListener('pointerenter',e=>this.handlers.hand(e,true,false));
 canvas.addEventListener('pointerleave',()=>{if(!this.drag){this.hovered='';this.highlight();this.handlers.hide();}});
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.stopImmediatePropagation();this.down(e);},{capture:true});
 canvas.addEventListener('pointermove',e=>{if(this.drag)e.stopImmediatePropagation();this.move(e);},{capture:true});
 canvas.addEventListener('pointerup',e=>{if(!this.drag)return;e.stopImmediatePropagation();this.up(e);},{capture:true});
 canvas.addEventListener('pointercancel',()=>{this.cancel();this.handlers.cancel();},{capture:true});
 canvas.addEventListener('lostpointercapture',()=>{if(this.drag){this.cancel();this.handlers.cancel();}});
 }
 resetView(){this.controls.target.set(.65,0,0);this.camera.position.set(.8,.8,7.7);this.controls.update();this.resize();}
 highlight(){const destinations=DESTINATIONS[this.state?.selectedItem]||[];for(const [key,part]of Object.entries(this.rig?.parts||{})){if(!part.material||!part.userData.handTarget)continue;part.material.emissive.set(key===this.hovered?0x54371a:destinations.includes(key)?0x173e2d:0x000000);}}
 resize(){const r=this.canvas.getBoundingClientRect();if(r.width&&r.height){this.renderer.setSize(r.width,r.height,false);this.camera.aspect=r.width/r.height;this.camera.updateProjectionMatrix();}}
 update(state){this.state=state;if(this.rig?.id!==state.id){this.cancel();if(this.rig){this.scene.remove(this.rig.group);disposeRig(this.rig);}this.rig=makeRepairRig(state.id);this.scene.add(this.rig.group);this.controls.target.set(.65,0,0);this.camera.position.set(.8,.8,7.7);this.controls.update();}updateRepairRig(this.rig,state);this.highlight();this.resize();}
 rayAt(e){const r=this.canvas.getBoundingClientRect();this.pointer.set((e.clientX-r.left)/r.width*2-1,1-(e.clientY-r.top)/r.height*2);this.scene.updateMatrixWorld(true);this.camera.updateMatrixWorld(true);this.ray.setFromCamera(this.pointer,this.camera);}
 pick(e,destinations){this.rayAt(e);const meshes=[];this.rig.group.traverse(o=>{if(!o.isMesh||!o.userData.handTarget)return;for(let p=o;p;p=p.parent)if(!p.visible)return;meshes.push(o);});const hits=this.ray.intersectObjects(meshes,false);return (destinations?hits.find(h=>destinations.includes(h.object.userData.handTarget)):null)||hits[0];}
 down(e){if(e.button!==0||!this.rig)return;const hit=this.pick(e,this.state.selectedItem?DESTINATIONS[this.state.selectedItem]:null);if(!hit){this.handlers.miss?.();return;}let id=hit.object.userData.handTarget;if(this.state.selectedItem&&DESTINATIONS[this.state.selectedItem]?.includes(id)){this.handlers.pick(id);return;}if(id.startsWith('doorSlide')&&(!this.state.power||this.state.obstacle)){this.handlers.door(this.state.doorPosition);return;}let grabbed=hit.object;if(id==='wheelHub'&&!this.state.wheelRemoved&&!this.state.wheelReplaced){id='wheel';grabbed=this.rig.parts.wheel;}const p={id,pointerId:e.pointerId,x:e.clientX,y:e.clientY,object:grabbed,original:grabbed.position.clone(),point:hit.point.clone(),base:this.state.doorPosition,rotation:this.state.rotation,plane:new THREE.Plane().setFromNormalAndCoplanarPoint(this.camera.getWorldDirection(new THREE.Vector3()),hit.point)};
 if(PIECES.has(id)){this.handlers.pick(id);if(this.state.selectedItem!==id)return;p.kind='piece';p.offset=hit.point.clone().sub(grabbed.getWorldPosition(new THREE.Vector3()));}
 else if(id.startsWith('screw')||id.startsWith('bolt')){this.handlers.pick(id);if(!this.state.toolMotion)return;p.kind='turn';const c=hit.object.getWorldPosition(new THREE.Vector3()).project(this.camera),r=this.canvas.getBoundingClientRect();p.cx=r.left+(c.x+1)*r.width/2;p.cy=r.top+(1-c.y)*r.height/2;p.angle=Math.hypot(e.clientX-p.cx,e.clientY-p.cy)>4?Math.atan2(e.clientY-p.cy,e.clientX-p.cx):null;}
 else if(id.startsWith('doorSlide'))p.kind='door';else if(id==='wheelHub'&&this.state.wheelReplaced)p.kind='wheel';else {this.handlers.pick(id);return;}
 this.drag=p;this.controls.enabled=false;this.canvas.setPointerCapture?.(e.pointerId);this.handlers.hand(e,true,Boolean(this.drag));e.preventDefault();}
 move(e){this.handlers.hand(e,true,Boolean(this.drag));if(!this.drag){const h=this.pick(e);this.canvas.style.cursor=h?'pointer':'default';this.hovered=h?.object.userData.handTarget||'';this.highlight();this.handlers.hover?.(this.hovered);return;}const p=this.drag;if(p.pointerId!==e.pointerId)return;p.moved ||= Math.hypot(e.clientX-p.x,e.clientY-p.y)>6;this.handlers.hand(e,true,Boolean(this.drag));this.rayAt(e);const point=this.ray.ray.intersectPlane(p.plane,new THREE.Vector3());if(!point)return;
 if(p.kind==='piece')p.object.position.copy(p.object.parent.worldToLocal(point.sub(p.offset)));
 else if(p.kind==='door')this.handlers.door(p.base+(point.x-p.point.x)*(p.id.endsWith('Left')?-100:100));
 else if(p.kind==='wheel'){const center=p.object.getWorldPosition(new THREE.Vector3());const a=Math.atan2(point.y-center.y,point.x-center.x);if(p.angle!==undefined)this.handlers.wheel(this.state.rotation+Math.abs(THREE.MathUtils.radToDeg(Math.atan2(Math.sin(a-p.angle),Math.cos(a-p.angle)))));p.angle=a;}
 else {const a=Math.atan2(e.clientY-p.cy,e.clientX-p.cx);if(p.angle!==null)this.handlers.turn(Math.atan2(Math.sin(a-p.angle),Math.cos(a-p.angle))/(Math.PI*2));p.angle=a;}}
 up(e){if(!this.drag||this.drag.pointerId!==e.pointerId)return;const p=this.drag;this.drag=null;p.object.position.copy(p.original);const moved=Math.hypot(e.clientX-p.x,e.clientY-p.y)>6||p.moved;if(!moved&&p.kind!=='piece')this.handlers.tap?.(p.id);if(p.kind==='piece'){if(moved){const hit=this.pick(e,DESTINATIONS[p.id]);let destination=hit&&DESTINATIONS[p.id]?.includes(hit.object.userData.handTarget)?hit.object.userData.handTarget:null;if(!destination){const rect=this.canvas.getBoundingClientRect();let distance=48;for(const key of DESTINATIONS[p.id]||[]){const object=this.rig.parts[key];if(!object?.visible)continue;const point=object.getWorldPosition(new THREE.Vector3()).project(this.camera),d=Math.hypot(rect.left+(point.x+1)*rect.width/2-e.clientX,rect.top+(1-point.y)*rect.height/2-e.clientY);if(d<distance){distance=d;destination=key;}}}if(destination)this.handlers.pick(destination);else this.handlers.cancel();}}this.controls.enabled=true;this.handlers.hide();try{this.canvas.releasePointerCapture(e.pointerId);}catch{}this.update(this.state);}
 cancel(){if(this.drag){this.drag.object.position.copy(this.drag.original);this.drag=null;this.controls.enabled=true;this.handlers?.hide();}}
 frame(){requestAnimationFrame(()=>this.frame());const dt=this.clock.getDelta();if(!this.visible||document.hidden||document.body.dataset.gameScreen!=='maintenance')return;if(this.rig?.id==='ventilation'&&this.state?.fanPassed){this.rig.parts.rotor.visible=true;this.rig.parts.cover.material.transparent=true;this.rig.parts.cover.material.opacity=.18;this.rig.parts.rotor.rotation.z+=dt*5;}this.controls.update();this.renderer.render(this.scene,this.camera);}
}
